module RSA_Encrypt (
    input wire clk,
    input wire rst,
    input wire [15:0] plaintext,
    input wire [15:0] e,
    input wire [15:0] n,
    output reg [15:0] ciphertext
);
    reg [31:0] temp;
    reg [15:0] exp_result;
    reg [4:0] count;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            ciphertext <= 16'b0;
            temp <= 32'b0;
            exp_result <= 16'b1;
            count <= 5'b0;
        end else begin
            if (count < e) begin
                temp <= (exp_result * plaintext) % n;
                exp_result <= temp[15:0];
                count <= count + 1;
            end else begin
                ciphertext <= exp_result;
                count <= 5'b0; // Reset count for next operation
            end
        end
    end
endmodule

