module dwt_hair (
    input clk,
    input rst,
    input [7:0] in_data,
    input valid,
    output reg [7:0] out_data,
    output reg ready
);
    reg [7:0] data_reg [0:7];
    integer i;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            for (i = 0; i < 8; i = i + 1) begin
                data_reg[i] <= 8'b0;
            end
            out_data <= 8'b0;
            ready <= 0;
        end else if (valid) begin
            // Load input data
            data_reg[0] <= in_data[0:0];
            data_reg[1] <= in_data[1:1];
            data_reg[2] <= in_data[2:2];
            data_reg[3] <= in_data[3:3];
            data_reg[4] <= in_data[4:4];
            data_reg[5] <= in_data[5:5];
            data_reg[6] <= in_data[6:6];
            data_reg[7] <= in_data[7:7];
            // Perform Haar DWT
            out_data[0] <= (data_reg[0] + data_reg[1]) >> 1; // Approximation
            out_data[1] <= (data_reg[2] + data_reg[3]) >> 1; // Approximation
            out_data[2] <= (data_reg[4] + data_reg[5]) >> 1; // Approximation
            out_data[3] <= (data_reg[6] + data_reg[7]) >> 1; // Approximation
            out_data[4] <= (data_reg[0] - data_reg[1]) >> 1; // Detail
            out_data[5] <= (data_reg[2] - data_reg[3]) >> 1; // Detail
