module aes_8bit (
    input wire clk,
    input wire rst,
    input wire [7:0] plaintext,
    input wire [127:0] key,
    output reg [7:0] ciphertext
);
    reg [127:0] round_key;

    // Key expansion (simplified)
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            round_key <= 0;
            ciphertext <= 0;
        end else begin
            // Simplified key expansion and XOR operation
            round_key <= key ^ {8'b0, plaintext}; // Example of mixing
            ciphertext <= plaintext ^ round_key[7:0]; // XOR with the first 8 bits of round key
        end
    end
endmodule

