module watchdog_timer (
    input wire clk,
    input wire reset,
    input wire [3:0] timeout_duration, // 4-bit input for timeout value
    output reg timeout
);

    reg [3:0] counter;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 4'b0;
            timeout <= 1'b0;
        end else begin
            if (counter < timeout_duration) begin
                counter <= counter + 1;
                timeout <= 1'b0;
            end else begin
                timeout <= 1'b1;
            end
        end
    end
endmodule

