module rng_lfsr (  
    input clk,  
    input reset,  
    output reg [4:0] random_out  
);  
    reg [4:0] lfsr;  
    wire feedback;  

    // Feedback polynomial: x^5 + x^2 + 1 (tap positions: 5 and 2)  
    assign feedback = lfsr[4] ^ lfsr[1];  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            lfsr <= 5'b00001; // Initial seed  
        end else begin  
            lfsr <= {lfsr[3:0], feedback};  
        end  
    end  

    always @(posedge clk) begin  
        random_out <= lfsr;  
    end  
endmodule

