module fractional_n_pll (  
    input wire clk_in,  
    input wire reset,  
    input wire [1:0] divider_select,  
    output reg clk_out  
);  

reg [3:0] state;  
reg [3:0] divider;  

always @(posedge clk_in or posedge reset) begin  
    if (reset) begin  
        state <= 0;  
        divider <= 4; // default divider value  
    end else begin  
        case (divider_select)  
            2'b00: divider <= 4; // Divide by 4  
            2'b01: divider <= 5; // Divide by 5  
            2'b10: divider <= 6; // Divide by 6  
            2'b11: divider <= 7; // Divide by 7  
            default: divider <= 4;  
        endcase  

        if (state < divider) begin  
            clk_out <= 1;  
            state <= state + 1;  
        end else begin  
            clk_out <= 0;  
            state <= 0;  
        end  
    end  
end  
endmodule

