module uart_transmitter (
    input wire clk,
    input wire rst,
    input wire start,
    input wire [7:0] data,
    output reg tx,
    output reg busy
);
    parameter BAUD_RATE = 9600; // Assume a clock of 50 MHz, for simplicity
    localparam CLOCK_DIVIDER = 50_000_000 / BAUD_RATE;

    reg [3:0] bit_index;
    reg [15:0] clock_counter;
    reg transmit;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            tx <= 1; // Idle state is high
            busy <= 0;
            bit_index <= 0;
            clock_counter <= 0;
            transmit <= 0;
        end else if (start && !busy) begin
            busy <= 1;
            bit_index <= 0;
            clock_counter <= 0;
            transmit <= 1;
        end else if (busy) begin
            if (clock_counter < CLOCK_DIVIDER - 1) begin
                clock_counter <= clock_counter + 1;
            end else begin
                clock_counter <= 0;
                if (bit_index < 8) begin
                    tx <= data[bit_index]; // Transmit each bit
                    bit_index <= bit_index + 1;
                end else begin
                    tx <= 1; // Stop bit
                    busy <= 0; // Transmission done
                end
            end
        end
    end
endmodule

