module stop_and_wait (  
    input wire clk,  
    input wire reset,  
    input wire [7:0] data_in,  
    input wire ack,  
    output reg [7:0] data_out,  
    output reg send,  
    output reg timeout  
);  
    parameter IDLE = 2'b00, SEND = 2'b01, WAIT_ACK = 2'b10;  
    reg [1:0] state, next_state;  
    reg [3:0] timer;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
            timer <= 0;  
            send <= 0;  
            timeout <= 0;  
        end else begin  
            state <= next_state;  
            if (next_state == WAIT_ACK) begin  
                timer <= timer + 1;  
                if (timer == 15) begin  
                    timeout <= 1;  
                end else begin  
                    timeout <= 0;  
                end  
            end else begin  
                timer <= 0;  
            end  
        end  
    end  

    always @(*) begin  
        case (state)  
            IDLE: begin  
                send = 0;  
                if (data_in != 8'b0) begin  
                    next_state = SEND;  
                end else begin  
                    next_state = IDLE;  
                end  
            end  
            SEND: begin  
                send = 1;  
                data_out = data_in;  
                next_state = WAIT_ACK;  
            end  
            WAIT_ACK: begin  
                send = 0;  
                if (ack) begin  
                    next_state = IDLE;  
                end else if (timeout) begin  
                    next_state = SEND;  
                end else begin  
                    next_state = WAIT_ACK;  
                end  
            end  
            default: next_state = IDLE;  
        endcase  
    end  
endmodule

