module dram_cell(  
    input wire clk,  
    input wire write_enable,  
    input wire data_in,  
    output reg data_out  
);  
    reg stored_bit;  

    always @(posedge clk) begin  
        if (write_enable) begin  
            stored_bit <= data_in;  
        end  
        data_out <= stored_bit;  
    end  
endmodule

module ethernet_mac_controller (  
    input wire clk,  
    input wire reset,  
    input wire [4:0] data_in,  
    output reg [4:0] data_out  
);  

    reg [4:0] data_reg;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            data_reg <= 5'b00000;  
            data_out <= 5'b00000;  
        end else begin  
            data_reg <= data_in + 1;  
            data_out <= data_reg;  
        end  
    end  
endmodule

module morphological_dilation (  
    input [8:0] image,  // 3x3 matrix flattened (image[8:0] = image[0][0], image[0][1], ..., image[2][2])  
    output reg result  
);  
    always @(*) begin  
        // Perform dilation: result is 1 if any pixel in the 3x3 is 1  
        if (|image)  
            result = 1;  
        else  
            result = 0;  
    end  
endmodule

module fir_filter (
    input [4:0] x, // 5-bit input
    input [4:0] x1, // delayed input (1 clock cycle)
    input [4:0] x2, // delayed input (2 clock cycles)
    input [4:0] x3, // delayed input (3 clock cycles)
    input [4:0] x4, // delayed input (4 clock cycles)
    output [4:0] y // 5-bit output
);
    assign y = (1*x) + (2*x1) + (3*x2) + (2*x3) + (1*x4);
endmodule

module multiplier_32bit (
    input [31:0] a,
