    reg [3:0] EX_MEM_opcode;

    reg [7:0] MEM_WB_result;
    reg [3:0] MEM_WB_opcode;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            result <= 8'b0;
            IF_ID_opcode <= 4'b0;
            IF_ID_operand1 <= 8'b0;
            IF_ID_operand2 <= 8'b0;
            ID_EX_opcode <= 4'b0;
            ID_EX_operand1 <= 8'b0;
            ID_EX_operand2 <= 8'b0;
            EX_MEM_result <= 8'b0;
            EX_MEM_opcode <= 4'b0;
            MEM_WB_result <= 8'b0;
            MEM_WB_opcode <= 4'b0;
        end else begin
            // Stage IF
            IF_ID_opcode <= opcode;
            IF_ID_operand1 <= operand1;
            IF_ID_operand2 <= operand2;

            // Stage ID
            ID_EX_opcode <= IF_ID_opcode;
            ID_EX_operand1 <= IF_ID_operand1;
            ID_EX_operand2 <= IF_ID_operand2;

            // Stage EX
            case (ID_EX_opcode)
                4'b0000: EX_MEM_result <= ID_EX_operand1 + ID_EX_operand2; // ADD
                4'b0001: EX_MEM_result <= ID_EX_operand1 - ID_EX_operand2; // SUB
                default: EX_MEM_result <= 8'b0;
            endcase
            EX_MEM_opcode <= ID_EX_opcode;

            // Stage MEM
            MEM_WB_result <= EX_MEM_result;
            MEM_WB_opcode <= EX_MEM_opcode;

            // Stage WB
            result <= MEM_WB_result;
        end
    end
endmodule

module checksum (
    input [4:0] data,
    output [1:0] checksum,
    output parity
);
    wire [2:0] sum;

    assign sum = data[0] + data[1] + data[2] + data[3] + data[4];
    assign checksum = sum[1:0]; // Taking modulo 4 (last 2 bits)
    assign parity = sum[0]; // Even (0) or odd (1)

endmodule

