module crc_4bit (  
    input [3:0] data_in,  
    output reg [3:0] crc_out,  
    input clk,  
    input rst  
);  
    always @(posedge clk or posedge rst) begin  
        if (rst)  
            crc_out <= 4'b0000;  
        else begin  
            // CRC calculation based on polynomial x^4 + x + 1  
            crc_out[3] <= data_in[3] ^ crc_out[0];  
            crc_out[2] <= data_in[2] ^ crc_out[3];  
            crc_out[1] <= data_in[1] ^ crc_out[2];  
            crc_out[0] <= data_in[0] ^ crc_out[1];  
        end  
    end  
endmodule

