module divider (
    input clk,
    input rst,
    input [3:0] dividend,
    input [3:0] divisor,
    output reg [3:0] quotient,
    output reg [3:0] remainder,
    output reg ready
);
    reg [3:0] temp_dividend;
    reg [3:0] temp_divisor;
    reg [3:0] count;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            quotient <= 4'b0000;
            remainder <= 4'b0000;
            temp_dividend <= 4'b0000;
            temp_divisor <= 4'b0000;
            count <= 4'b0000;
            ready <= 0;
        end else if (count == 0) begin
            if (divisor != 0) begin
                temp_dividend <= dividend;
                temp_divisor <= divisor;
                quotient <= 0;
                remainder <= 0;
                count <= 4; // Start the division process for 4 bits
            end else begin
                // Handle division by zero, keep outputs unchanged
                ready <= 0;
            end
        end else begin
            if (temp_dividend >= temp_divisor) begin
                temp_dividend <= temp_dividend - temp_divisor;
                quotient <= quotient + 1;
            end
            count <= count - 1;

            if (count == 1) begin
                remainder <= temp_dividend;
                ready <= 1; // Indicate division is complete
            end
        end
    end
endmodule

