module butterworth_filter (  
    input clk,  
    input reset,  
    input [4:0] x,  
    output reg [4:0] y  
);  
    reg [4:0] y_prev1, y_prev2;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            y <= 5'b0;  
            y_prev1 <= 5'b0;  
            y_prev2 <= 5'b0;  
        end else begin  
            y <= (x + y_prev1 + y_prev2) >> 2; // Example formula for Butterworth filter  
            y_prev2 <= y_prev1;  
            y_prev1 <= y;  
        end  
    end  
endmodule

