module aes_8bit (  
    input wire clk,  
    input wire reset,  
    input wire [7:0] data_in,  
    input wire [3:0] round_key,  
    output reg [7:0] data_out  
);  

    reg [1:0] state;  
    reg [7:0] sbox [0:15];  

    initial begin  
        // Initialize the S-Box for SubBytes transformation  
        sbox[0] = 8'h63; sbox[1] = 8'h7c; sbox[2] = 8'h77; sbox[3] = 8'h7b;  
        sbox[4] = 8'hf2; sbox[5] = 8'h6b; sbox[6] = 8'h6f; sbox[7] = 8'hc5;  
        sbox[8] = 8'h30; sbox[9] = 8'h01; sbox[10] = 8'h67; sbox[11] = 8'h2b;  
        sbox[12] = 8'hfe; sbox[13] = 8'hd7; sbox[14] = 8'hab; sbox[15] = 8'h76;  
    end  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= 0;  
            data_out <= 8'h00;  
        end else begin  
            case (state)  
                2'b00: begin  
                    // SubBytes transformation  
                    data_out <= sbox[data_in[3:0]] ^ round_key;  
                    state <= 2'b01;  
                end  
                2'b01: begin  
                    // ShiftRows transformation (for 8-bit, simply rotate right)  
                    data_out <= {data_out[6:0], data_out[7]} ^ round_key;  
                    state <= 2'b10;  
                end  
                2'b10: begin  
                    // Finish the round  
                    state <= 2'b00;  
                end  
            endcase  
        end  
    end  
endmodule

