module mux2to1 (
    input wire [3:0] in0,
    input wire [3:0] in1,
    input wire sel,
    output wire [3:0] out
);
    assign out = sel ? in1 : in0;
endmodule

module iir_filter #(parameter COEFF_A1 = 16'h0002, COEFF_A2 = 16'h0001, COEFF_B0 = 16'h0001, COEFF_B1 = 16'h0002, COEFF_B2 = 16'h0001) (  
    input clk,  
    input rst,  
    input signed [15:0] x,  
    output reg signed [15:0] y  
);  

    reg signed [15:0] x1, x2;  
    reg signed [15:0] y1, y2;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            y <= 16'h0000;  
            x1 <= 16'h0000;  
            x2 <= 16'h0000;  
            y1 <= 16'h0000;  
            y2 <= 16'h0000;  
        end else begin  
            y <= (COEFF_B0 * x + COEFF_B1 * x1 + COEFF_B2 * x2 - COEFF_A1 * y1 - COEFF_A2 * y2) >>> 3;  
            x2 <= x1;  
            x1 <= x;  
            y2 <= y1;  
            y1 <= y;  
        end  
    end  
endmodule

module phase_shifter(  
    input clk,  
    input reset,  
    input [2:0] phase_in,  
    output reg [2:0] phase_out  
);  
    always @(posedge clk or posedge reset) begin  
        if (reset)  
            phase_out <= 3'b000;  
        else  
            phase_out <= (phase_in + 3'b001) % 8;  
    end  
endmodule

