module pll (  
    input clk,  
    input reset,  
    input [7:0] freq_in,  
    output reg [7:0] freq_out  
);  
    reg [7:0] phase_error;  
    reg [7:0] loop_filter;  
    reg [7:0] vco_output;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            phase_error <= 8'b0;  
            loop_filter <= 8'b0;  
            vco_output <= 8'b0;  
            freq_out <= 8'b0;  
        end else begin  
            // Phase Detector (simple implementation)  
            phase_error <= freq_in - vco_output;  
            // Loop Filter (first order)  
            loop_filter <= loop_filter + phase_error;  
            // Voltage Controlled Oscillator (VCO) output  
            vco_output <= loop_filter;  
            // Output frequency is double the input frequency when locked  
            freq_out <= freq_in * 2;  
        end  
    end  
endmodule

