module uart_transmitter (
    input clk,
    input rst,
    input [7:0] data_in,
    input start,
    output reg tx,
    output reg busy
);
    parameter BAUD_RATE_DIV = 16; // Adjust for your clock
    reg [3:0] bit_counter;
    reg [3:0] baud_counter;
    reg [1:0] state;
    reg [7:0] shift_reg;

    localparam IDLE = 2'b00,
               START = 2'b01,
               DATA = 2'b10,
               STOP = 2'b11;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            tx <= 1;
            busy <= 0;
            state <= IDLE;
            bit_counter <= 0;
            baud_counter <= 0;
        end else begin
            case (state)
                IDLE: begin
                    tx <= 1; // Idle state is high
                    if (start && !busy) begin
                        busy <= 1;
                        shift_reg <= data_in;
                        bit_counter <= 0;
                        baud_counter <= 0;
                        state <= START;
                    end
                end

                START: begin
                    if (baud_counter < BAUD_RATE_DIV - 1) begin
                        baud_counter <= baud_counter + 1;
                    end else begin
                        baud_counter <= 0;
                        tx <= 0; // Start bit
                        state <= DATA;
                    end
                end

                DATA: begin
                    if (baud_counter < BAUD_RATE_DIV - 1) begin
                        baud_counter <= baud_counter + 1;
                    end else begin
                        baud_counter <= 0;
                        tx <= shift_reg[bit_counter]; // Send current bit
                        if (bit_counter < 7) begin
                            bit_counter <= bit_counter + 1;
                        end else begin
                            state <= STOP;
                        end
                    end
                end

                STOP: begin
                    if (baud_counter < BAUD_RATE_DIV - 1) begin
                        baud_counter <= baud_counter + 1;
                    end else begin
                        baud_counter <= 0;
                        tx <= 1; // Stop bit
                        busy <= 0;
                        state <= IDLE;
                    end
                end
            endcase
        end
    end
endmodule

